#include <bits/stdc++.h>
using namespace std; typedef long long ll;
vector<ll> mn, lz;  // lazy segtree over beauty thresholds 1..m
void build(int nd,int l,int r,const vector<ll>&in){
    if(l==r){mn[nd]=in[l];return;}
    int md=(l+r)/2; build(2*nd,l,md,in); build(2*nd+1,md+1,r,in); mn[nd]=min(mn[2*nd],mn[2*nd+1]);
}
void add(int nd,int l,int r,int ql,int qr,ll v){
    if(qr<l||r<ql) return;
    if(ql<=l&&r<=qr){mn[nd]+=v; lz[nd]+=v; return;}
    int md=(l+r)/2; add(2*nd,l,md,ql,qr,v); add(2*nd+1,md+1,r,ql,qr,v);
    mn[nd]=min(mn[2*nd],mn[2*nd+1])+lz[nd];
}
ll qry(int nd,int l,int r,int ql,int qr){
    if(qr<l||r<ql) return LLONG_MAX/4;
    if(ql<=l&&r<=qr) return mn[nd];
    int md=(l+r)/2;
    return min(qry(2*nd,l,md,ql,qr),qry(2*nd+1,md+1,r,ql,qr))+lz[nd];
}
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n,m; ll k; scanf("%d %d %lld",&n,&m,&k);
        vector<ll> cnt(m+2,0), in(m+2,0);
        for(int i=0;i<m;i++){int v; scanf("%d",&v); cnt[v]++;}
        for(int v=m,ge=0;v>=1;v--){ge+=cnt[v]; in[v]=ge;}  // boxes with beauty >= v
        vector<int> x(n); vector<ll> y(n), z(n), d(n); ll sumY=0;
        for(int i=0;i<n;i++){scanf("%d %lld %lld",&x[i],&y[i],&z[i]); d[i]=z[i]-y[i]; sumY+=y[i];}
        mn.assign(4*m+4,0); lz.assign(4*m+4,0); build(1,1,m,in);
        vector<int> ord(n); iota(ord.begin(),ord.end(),0);
        sort(ord.begin(),ord.end(),[&](int p,int q){return d[p]>d[q];});
        vector<char> inB(n,0); ll bcnt=0;
        for(int i:ord) if(qry(1,1,m,1,x[i])>=1){add(1,1,m,1,x[i],-1); inB[i]=1; bcnt++;}
        vector<ll> rest; for(int i=0;i<n;i++) if(!inB[i]) rest.push_back(d[i]);
        sort(rest.begin(),rest.end());
        ll slack=k-sumY, used=0, take=0;
        for(ll v:rest){ if(used+v>slack) break; used+=v; take++; }
        printf("%lld\n",bcnt+take);
    }
}

