#include <bits/stdc++.h>
using namespace std; typedef long long ll; const ll MOD=1e9+7;
ll pw(ll b,ll e){ll r=1; b%=MOD; while(e){ if(e&1) r=r*b%MOD; b=b*b%MOD; e>>=1;} return r;}
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<ll> so, sc;          // stack: odd part, held power of 2
        ll fixedSum=0, stackSum=0;  // popped odd parts are final; stack value o*2^c
        string out;
        for(int i=0;i<n;i++){
            ll a; scanf("%lld",&a);
            ll o=a, c=0; while(o%2==0){o/=2; c++;}
            while(!so.empty()){
                ll to=so.back(), tc=sc.back();
                bool better = (c>=31) || ((o<<c) >= to);
                if(!better) break;
                fixedSum=(fixedSum+to)%MOD;
                stackSum=(stackSum - to%MOD*pw(2,tc)%MOD + MOD)%MOD;
                c+=tc; so.pop_back(); sc.pop_back();
            }
            so.push_back(o); sc.push_back(c);
            stackSum=(stackSum + o%MOD*pw(2,c))%MOD;
            out += to_string((fixedSum+stackSum)%MOD) + (i+1<n?" ":"");
        }
        printf("%s\n",out.c_str());
    }
}

