        int n; scanf("%d",&n);
        vector<int> a(n), b(n);
        for(auto &v:a) scanf("%d",&v);
        for(auto &v:b) scanf("%d",&v);
        int LG=1; while((1<<LG)<=n) LG++;
        vector<vector<int>> mx(LG, vector<int>(n)), mn(LG, vector<int>(n));
        mx[0]=a; mn[0]=b;
        for(int k=1;k<LG;k++) for(int i=0;i+(1<<k)<=n;i++){
            mx[k][i]=max(mx[k-1][i], mx[k-1][i+(1<<(k-1))]);
            mn[k][i]=min(mn[k-1][i], mn[k-1][i+(1<<(k-1))]);
        }
        auto qmax=[&](int l,int r){int k=31-__builtin_clz(r-l+1); return max(mx[k][l], mx[k][r-(1<<k)+1]);};
        auto qmin=[&](int l,int r){int k=31-__builtin_clz(r-l+1); return min(mn[k][l], mn[k][r-(1<<k)+1]);};
        vector<vector<int>> pos(n+1);
        for(int i=0;i<n;i++) pos[a[i]].push_back(i);
        bool ok=true;
        for(int i=0;i<n && ok;i++){
            if(a[i]>b[i]){ok=false; break;}
            if(a[i]==b[i]) continue;
            int x=b[i]; bool g=false;
            auto &P=pos[x];
            auto it=upper_bound(P.begin(),P.end(),i);      // first position > i
            if(it!=P.begin()){ int j=*prev(it); if(qmax(j,i)<=x && qmin(j,i)>=x) g=true; }
            if(!g && it!=P.end()){ int j=*it; if(qmax(i,j)<=x && qmin(i,j)>=x) g=true; }
            if(!g) ok=false;
        }
        puts(ok?"YES":"NO");
    }
}

