        for(auto &v:a) scanf("%d",&v);
        string res(n,'0');
        for(int k=1;k<=n;k++){              // k-compression, m windows
            int m=n-k+1; vector<char> seen(m+1,0); bool ok=true;
            deque<int> dq;                  // sliding-window minimum
            for(int i=0;i<n && ok;i++){
                while(!dq.empty() && a[dq.back()]>=a[i]) dq.pop_back();
                dq.push_back(i);
                if(dq.front()<=i-k) dq.pop_front();
                if(i>=k-1){
                    int b=a[dq.front()];
                    if(b>m || seen[b]) ok=false; else seen[b]=1;
                }
            }
            res[k-1]= ok?'1':'0';
        }
        printf("%s\n",res.c_str());
    }
}

