#include <bits/stdc++.h>
using namespace std;
int main(){
    int T; scanf("%d",&T);
    while(T--){
        int n; scanf("%d",&n);
        vector<int> a(n), b(n,0), cnt(n+2,0);
        for(auto &x:a){ scanf("%d",&x); cnt[x]++; }
        vector<int> ge(n+2,0), gt(n+2,0);   // ge[p] = #a>=p, gt[p] = #a>p
        for(int p=n;p>=0;p--){ ge[p]=ge[p+1]+cnt[p]; gt[p]=ge[p+1]; }
        bool found=false;
        for(int p=0;p<=n && !found;p++) for(int mode=0;mode<2 && !found;mode++){
            // mode 1: a==p are positive; mode 0: a==p are negative
            if((mode? ge[p] : gt[p]) != p) continue;
            vector<int> P, N;
            for(int i=0;i<n;i++) ((a[i]>p || (mode && a[i]==p))? P : N).push_back(i);
            int q=n-p;
            sort(N.begin(),N.end(),[&](int x,int y){return a[x]>a[y];});  // Q = p-a ascending
            vector<int> X(q+2); X[0]=0; X[q+1]=p;
            for(int y=0;y<q;y++) X[y+1]=p-a[N[y]];
            vector<vector<int>> bk(q+1);
            bool ok=true;
            for(int i:P){ int R=a[i]-p; if(R<0||R>q){ok=false;break;} bk[R].push_back(i); }
            for(int y=0;y<=q&&ok;y++) if((int)bk[y].size()!=X[y+1]-X[y]) ok=false;
            if(!ok) continue;
            int t=0;                                   // path: P steps at height y, then N step
            for(int y=0;y<=q;y++){ for(int i:bk[y]) b[i]=++t; if(y<q) b[N[y]]=-(++t); }
            found=true;
        }
        if(!found){ puts("NO"); continue; }
        puts("YES");
        for(int i=0;i<n;i++) printf("%d ",b[i]);
        printf("\n");
    }
}

