using namespace std;
const long long MOD=998244353;
int main(){
    int T; scanf("%d",&T);
    while(T--){
        int n,k; scanf("%d %d",&n,&k);
        vector<int> a(n), pos(n+1), wall(n+1,0), b(k);
        for(int i=0;i<n;i++){ scanf("%d",&a[i]); pos[a[i]]=i; }
        for(int i=0;i<k;i++){ scanf("%d",&b[i]); wall[b[i]]=i+1; }   // wall = index in b (1-based)
        vector<int> prv(n), nxt(n);
        for(int i=0;i<n;i++){ prv[i]=i-1; nxt[i]=i+1; }
        vector<char> present(n,1);
        long long ans=1;
        for(int i=0;i<k;i++){
            int p=pos[b[i]];
            if(!present[p]){ ans=0; break; }
            int L=prv[p], R=nxt[p];
            bool lok = L>=0 && (wall[a[L]]==0 || wall[a[L]]<=i+1);   // neighbor is not a future b
            bool rok = R<n && (wall[a[R]]==0 || wall[a[R]]<=i+1);
            int c=(int)lok+(int)rok;
            if(c==0){ ans=0; break; }
            ans=ans*c%MOD;
            int x = lok ? L : R;                                     // always take left when possible
            present[x]=0;
            int px=prv[x], nx=nxt[x];
            if(px>=0) nxt[px]=nx;
            if(nx<n) prv[nx]=px;
        }
        printf("%lld\n",ans);
    }
}

