int main(){
    int n; scanf("%d",&n);
    vector<int> a(n), b(n+1), pb(n+1,0);          // pb[v] = 1-based index of v in pile, 0 if in hand
    for(auto &x:a) scanf("%d",&x);
    for(int j=1;j<=n;j++){ scanf("%d",&b[j]); if(b[j]) pb[b[j]]=j; }
    int mx=0;                                     // T >= n: card x must be drawn by step T-n+x-1
    for(int x=1;x<=n;x++) if(pb[x]) mx=max(mx,pb[x]-x+1);
    long long best=n+mx;
    if(b[n]){                                     // T < n: pile suffix must be 1..n-T
        int T=n-b[n]; bool ok=(T>=0 && T<n);
        for(int j=T+1;j<=n&&ok;j++) if(b[j]==0 || j-b[j]!=T) ok=false;
        for(int j=1;j<=T&&ok;j++){ int v=n-T+j; if(pb[v]>=j) ok=false; }
        if(ok) best=min(best,(long long)T);
    }
    printf("%lld\n",best);
}

