        else if(u[l]<t[l]) res[i]=u;                   // already smaller
        else res[i]=u.substr(0,l);                     // cut at first larger letter
    }
    string out;
    for(int i=0;i<n;i++){ out+='#'; out+=res[i]; out+='\n'; }
    cout<<out;
}

