    sort(a.begin(),a.end());
    vector<int> cnt;                                  // occurrences of each topic
    for(int i=0;i<n;){ int j=i; while(j<n && a[j]==a[i]) j++; cnt.push_back(j-i); i=j; }
    sort(cnt.begin(),cnt.end());
    long long best=0;
    for(long long s=1;s<=n;s++){
        multiset<int> ms;                             // topics that can host the first contest of size s
        for(auto it=lower_bound(cnt.begin(),cnt.end(),(int)s); it!=cnt.end(); ++it) ms.insert(*it);
        long long total=0;
        for(long long need=s; ; need*=2){             // greedy: smallest topic count >= need
            auto it=ms.lower_bound((int)need);
            if(it==ms.end()) break;
            total+=need; ms.erase(it);
        }
        best=max(best,total);
    }
    printf("%lld\n",best);
}

#include <bits/stdc++.h>
using namespace std;
int n; long long T; vector<int> a, t;
// s points need s solved problems with a >= s; feasible iff the s smallest times fit in T
bool pick(int s, vector<int> &out){
    vector<int> c;
    for(int i=0;i<n;i++) if(a[i]>=s) c.push_back(i);
    if((int)c.size()<s) return false;
    sort(c.begin(),c.end(),[&](int x,int y){return t[x]<t[y];});
    long long sum=0; out.clear();
    for(int j=0;j<s;j++){ sum+=t[c[j]]; out.push_back(c[j]); }
    return sum<=T;
}
int main(){
    scanf("%d %lld",&n,&T);
    a.resize(n); t.resize(n);
    for(int i=0;i<n;i++) scanf("%d %d",&a[i],&t[i]);
    int lo=0, hi=n;                          // feasibility is monotone in s, so binary search
    while(lo<hi){
        int mid=(lo+hi+1)/2; vector<int> tmp;
        if(pick(mid,tmp)) lo=mid; else hi=mid-1;
    }
    vector<int> ans; pick(lo,ans);
    printf("%d\n%d\n",lo,(int)ans.size());
    for(int x:ans) printf("%d ",x+1);
    printf("\n");
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; scanf("%d",&n);
    vector<long long> pos;
    for(int i=0;i<n;i++){ int x; scanf("%d",&x); if(x) pos.push_back(i); }
    int S=pos.size();
    vector<long long> pre(S+1,0);
    for(int i=0;i<S;i++) pre[i+1]=pre[i]+pos[i];
    long long best=-1;
    for(int p=2;p<=S;p++){
        if(S%p) continue;
        bool prime=true; for(int d=2;d*d<=p;d++) if(p%d==0){prime=false;break;}
        if(!prime) continue;
        long long cost=0;
        for(int g=0; g<S; g+=p){                      // each block of p ones gathers into one box
            int mid=g+(p-1)/2;
            long long m=pos[mid];
            cost += m*(mid-g) - (pre[mid]-pre[g]);
            cost += (pre[g+p]-pre[mid+1]) - m*(g+p-1-mid);
        }
        if(best<0 || cost<best) best=cost;
    }
    printf("%lld\n",best);
}

#include <bits/stdc++.h>
using namespace std;
int par[505];
int fnd(int x){ return par[x]==x? x : par[x]=fnd(par[x]); }
int main(){
    int T; scanf("%d",&T);
    while(T--){
        int n; scanf("%d",&n);
        vector<string> s(n); char buf[512];
        for(int i=0;i<n;i++){ scanf("%s",buf); s[i]=buf; }
        bool ok=true;
        for(int i=0;i<n;i++) if(s[i][i]!='1') ok=false;
        vector<pair<int,int>> E;                       // edges = covering pairs of reachability
        for(int u=0;u<n && ok;u++) for(int v=0;v<n;v++){
            if(u==v || s[u][v]!='1') continue;
            bool cover=true;
            for(int w=0;w<n && cover;w++) if(w!=u && w!=v && s[u][w]=='1' && s[w][v]=='1') cover=false;
            if(cover) E.push_back({u,v});
        }
        if(ok && (int)E.size()!=n-1) ok=false;
        if(ok){                                        // n-1 edges, no cycle => tree
            for(int i=0;i<n;i++) par[i]=i;
            for(auto [u,v]:E){ int a=fnd(u), b=fnd(v); if(a==b){ ok=false; break; } par[a]=b; }
        }
        if(ok){                                        // verify the tree reproduces the matrix
            vector<vector<int>> adj(n);
            for(auto [u,v]:E) adj[u].push_back(v);
            for(int src=0;src<n && ok;src++){
                vector<char> vis(n,0); vector<int> st{src}; vis[src]=1;
                while(!st.empty()){ int x=st.back(); st.pop_back(); for(int y:adj[x]) if(!vis[y]){ vis[y]=1; st.push_back(y);} }
                for(int j=0;j<n;j++) if(vis[j]!=(s[src][j]=='1')){ ok=false; break; }
            }
        }
        if(!ok){ puts("No"); continue; }
