    for(int j=0;j<m;j++) scanf("%d %d",&L[j],&R[j]);
    // answer = max over i != j of a_i - a_j + (#segments covering j but not i); i = max, j = min
    long long best=0; int bi=-1, bj=-1;
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        if(i==j) continue;
        long long cnt=0;
        for(int s=0;s<m;s++){
            bool cj = L[s]<=j+1 && j+1<=R[s];
            bool ci = L[s]<=i+1 && i+1<=R[s];
            if(cj && !ci) cnt++;
        }
        long long val=a[i]-a[j]+cnt;
        if(val>best){ best=val; bi=i; bj=j; }
    }
    vector<int> chosen;
    if(bi>=0) for(int s=0;s<m;s++){
        bool cj = L[s]<=bj+1 && bj+1<=R[s];
        bool ci = L[s]<=bi+1 && bi+1<=R[s];
        if(cj && !ci) chosen.push_back(s+1);
    }
