#include <bits/stdc++.h>
using namespace std;
const int B=30, MAXN=9000005;
int ch[MAXN][2], cntN[MAXN], tot=1;                  // binary trie over P with counts
void ins(int x){
    int u=0; cntN[u]++;
    for(int b=B-1;b>=0;b--){ int c=x>>b&1; if(!ch[u][c]) ch[u][c]=tot++; u=ch[u][c]; cntN[u]++; }
}
int extract(int x){                                  // remove the P value y minimizing x^y, return y
    int u=0, y=0; cntN[u]--;
    for(int b=B-1;b>=0;b--){
        int c=x>>b&1;
        int v=ch[u][c];
        if(!v || cntN[v]==0){ c^=1; v=ch[u][c]; }   // prefer the same bit (smaller xor)
        y|=c<<b; u=v; cntN[u]--;
    }
    return y;
}
int main(){
    int n; scanf("%d",&n);
    vector<int> A(n), P(n);
    for(auto &x:A) scanf("%d",&x);
    for(auto &x:P){ scanf("%d",&x); ins(x); }
    // greedy: for each position take the smallest possible XOR (lexicographic minimality)
    string out;
    for(int i=0;i<n;i++){
        int y=extract(A[i]);
        out += to_string(A[i]^y);
        out += (i+1<n?' ':'\n');
    }
    fputs(out.c_str(),stdout);
}

