#include <bits/stdc++.h>
using namespace std;
// beauty of a ribbon = max letter count after n changes (substring occurrences <= count of its first letter)
long long calc(long long n, const string &s){
    long long L=s.size();
    if(L==1) return 1;                                 // one letter, must change it each turn
    int f[256]={0}; long long m=0;
    for(unsigned char c:s) m=max<long long>(m,++f[c]);
    long long d=L-m;                                   // letters not yet equal to the best letter
    if(n<d) return m+n;                                // each turn adds at most one to the count
    if(d>0) return L;                                  // extra turns can be absorbed by a non-target letter
    return (n==1)? L-1 : L;                            // all equal: one turn must break it, n>=2 can restore it
}
int main(){
    long long n; string a,b,c;
    cin>>n>>a>>b>>c;
    long long va=calc(n,a), vb=calc(n,b), vc=calc(n,c);
    long long mx=max({va,vb,vc});
    int cnt=(va==mx)+(vb==mx)+(vc==mx);
    if(cnt>1) puts("Draw");
    else if(va==mx) puts("Kuro");
    else if(vb==mx) puts("Shiro");
    else puts("Katie");
}

#include <bits/stdc++.h>
using namespace std;
int n; vector<int> bit; int LOG;
void upd(int i,int v){ for(;i<=n;i+=i&-i) bit[i]+=v; }
int kth(int k){                                      // smallest index with prefix count >= k
    int pos=0;
    for(int pw=LOG;pw;pw>>=1)
        if(pos+pw<=n && bit[pos+pw]<k){ pos+=pw; k-=bit[pos]; }
    return pos+1;
}
int main(){
    scanf("%d",&n);
    vector<int> a(n+1);
    for(int i=1;i<=n;i++) scanf("%d",&a[i]);
    int m; scanf("%d",&m);
    vector<vector<pair<int,int>>> byK(n+1);          // byK[k] = (pos, query id)
    for(int q=0;q<m;q++){ int k,p; scanf("%d %d",&k,&p); byK[k].push_back({p,q}); }
    vector<int> ord(n); iota(ord.begin(),ord.end(),1);
    sort(ord.begin(),ord.end(),[&](int x,int y){ return a[x]!=a[y] ? a[x]>a[y] : x<y; });
    bit.assign(n+1,0); LOG=1; while(LOG*2<=n) LOG*=2;
    vector<int> ans(m);
    for(int k=1;k<=n;k++){
        upd(ord[k-1],1);                             // top-k by (value desc, index asc)
        for(auto &[p,q]:byK[k]) ans[q]=a[kth(p)];   // p-th chosen index in position order
    }
    string out;
    for(int q=0;q<m;q++){ out+=to_string(ans[q]); out+='\n'; }
    fputs(out.c_str(),stdout);
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int m; scanf("%d",&m);
    while(m--){
        int n; long long T,a,b; scanf("%d %lld %lld %lld",&n,&T,&a,&b);
        vector<int> ty(n), t(n);
        for(auto &x:ty) scanf("%d",&x);
        for(auto &x:t) scanf("%d",&x);
        vector<int> ord(n); iota(ord.begin(),ord.end(),0);
        sort(ord.begin(),ord.end(),[&](int x,int y){return t[x]<t[y];});
        long long totE=0,totH=0; for(int x:ty) (x?totH:totE)++;
        long long sumM=0, inE=0, inH=0, best=0;
        for(int k=0;k<=n;k++){                       // first k problems (by t) are mandatory
            long long lo = (k>0? t[ord[k-1]] : 0);
            long long hi = (k<n? t[ord[k]]-1 : T);
            if(lo<=hi && sumM<=hi){                   // leaving at hi is best within this range
                long long budget=hi-sumM;
                long long cA=totE-inE, cB=totH-inH;
                long long x=min(cA, budget/a);
                long long rem=budget-x*a;
                long long y=min(cB, rem/b);
                best=max(best,(long long)k+x+y);
            }
            if(k<n){ int p=ord[k]; sumM += ty[p]? b : a; (ty[p]?inH:inE)++; }
        }
        printf("%lld\n",best);
    }
}

